tps://registry.npmjs.org/yocto-queue/-/yocto-queue-0.1.0.tgz\",\n+      \"integrity\": \"sha512-rVksvsnNCdJ/ohGc6xgPwyN8eheCxsiLM8mxuE/t/mOVqJewPuO1miLpTHQiRgTKCLexL4MeAFVagts7HmNZ2Q==\",\n+      \"dev\": true,\n+      \"license\": \"MIT\",\n+      \"engines\": {\n+        \"node\": \">=10\"\n+      },\n+      \"funding\": {\n+        \"url\": \"https://github.com/sponsors/sindresorhus\"\n+      }\n+    }\n+  }\n+}\n--- /dev/null\n+++ b/package.json\n@@ -0,0 +1,27 @@\n+{\n+  \"name\": \"pantry-app\",\n+  \"version\": \"0.1.0\",\n+  \"private\": true,\n+  \"type\": \"module\",\n+  \"engines\": {\n+    \"node\": \">=24\"\n+  },\n+  \"scripts\": {\n+    \"format\": \"prettier --write .\",\n+    \"format:check\": \"prettier --check .\",\n+    \"lint\": \"eslint src\",\n+    \"typecheck\": \"tsc --noEmit\",\n+    \"build\": \"tsc\",\n+    \"test\": \"node --test tests/pantry.test.mjs tests/storage.test.mjs\",\n+    \"journey\": \"node scripts/journey.mjs\",\n+    \"check\": \"npm run format:check && npm run lint && npm run typecheck && npm run build && npm test && npm run journey\",\n+    \"start\": \"node scripts/preview.mjs\"\n+  },\n+  \"devDependencies\": {\n+    \"typescript\": \"5.9.3\",\n+    \"eslint\": \"9.39.1\",\n+    \"typescript-eslint\": \"8.48.1\",\n+    \"prettier\": \"3.7.4\",\n+    \"playwright-core\": \"1.57.0\"\n+  }\n+}\n--- /dev/null\n+++ b/scripts/journey.mjs\n@@ -0,0 +1,131 @@\n+import { chromium } from \"playwright-core\";\n+import assert from \"node:assert/strict\";\n+import { preview } from \"./preview.mjs\";\n+\n+const server = await preview();\n+let browser;\n+const observations = [];\n+try {\n+  browser = await chromium.launch({ channel: \"chrome\", headless: true });\n+  const context = await browser.newContext();\n+  const page = await context.newPage();\n+  const errors = [];\n+  page.on(\"pageerror\", (error) => errors.push(error.message));\n+  const remote = [];\n+  page.on(\"request\", (request) => {\n+    if (!request.url().startsWith(server.url)) remote.push(request.url());\n+  });\n+  await page.goto(server.url);\n+  const add = async (name) => {\n+    await page.getByLabel(\"Item name\", { exact: true }).fill(name);\n+    await page.getByRole(\"button\", { name: \"Add item\", exact: true }).click();\n+  };\n+  await add(\"Rice\");\n+  await page.getByRole(\"checkbox\", { name: \"Need Rice\", exact: true }).check();\n+  await page\n+    .getByRole(\"button\", { name: \"Shopping list\", exact: true })\n+    .click();\n+  assert.equal(\n+    await page\n+      .getByRole(\"checkbox\", { name: \"Need Rice\", exact: true })\n+      .isChecked(),\n+    true,\n+  );\n+  await page.reload();\n+  await page\n+    .getByRole(\"button\", { name: \"Shopping list\", exact: true })\n+    .click();\n+  assert.equal(\n+    await page\n+      .getByRole(\"checkbox\", { name: \"Need Rice\", exact: true })\n+      .isChecked(),\n+    true,\n+  );\n+  observations.push(\n+    \"Observed add Rice, mark needed, shopping-list Rice and retained needed Rice after reload.\",\n+  );\n+  await page.getByRole(\"button\", { name: \"Pantry\", exact: true }).click();\n+  await add(\" rice \");\n+  assert.equal(await page.getByRole(\"checkbox\").count(), 1);\n+  assert.equal(\n+    await page\n+      .getByRole(\"checkbox\", { name: \"Need Rice\", exact: true })\n+      .isChecked(),\n+    true,\n+  );\n+  await add(\"Brown Rice\");\n+  await add(\"White Rice\");\n+  assert.equal(await page.getByRole(\"checkbox\").count(), 3);\n+  observations.push(\n+    \"Observed trimmed case-insensitive reuse and distinct full-name variants.\",\n+  );\n+  await page.evaluate(() => {\n+    window.__restoreSave = Storage.prototype.setItem;\n+    Storage.prototype.setItem = () => {\n+      throw new DOMException(\"blocked\", \"QuotaExceededError\");\n+    };\n+  });\n+  await add(\"Beans\");\n+  await page.getByRole(\"checkbox\", { name: \"Need Beans\", exact: true }).check();\n+  assert.match(await page.locator(\"#save-status\").innerText(), /unsaved/);\n+  await page.getByRole(\"button\", { name: \"Retry saving\", exact: true }).click();\n+  assert.match(await page.locator(\"#save-status\").innerText(), /unsaved/);\n+  await add(\"Lentils\");\n+  await page\n+    .getByRole(\"button\", { name: \"Shopping list\", exact: true })\n+    .click();\n+  assert.equal(\n+    await page\n+      .getByRole(\"checkbox\", { name: \"Need Beans\", exact: true })\n+      .isChecked(),\n+    true,\n+  );\n+  await page.evaluate(() => {\n+    Storage.prototype.setItem = window.__restoreSave;\n+  });\n+  await page.getByRole(\"button\", { name: \"Retry saving\", exact: true }).click();\n+  assert.equal(\n+    await page.locator(\"#save-status\").innerText(),\n+    \"Saved locally.\",\n+  );\n+  assert.equal(\n+    await page\n+      .getByRole(\"button\", { name: \"Retry saving\", exact: true })\n+      .isVisible(),\n+    false,\n+  );\n+  await page.reload();\n+  await page\n+    .getByRole(\"button\", { name: \"Shopping list\", exact: true })\n+    .click();\n+  assert.equal(\n+    await page\n+      .getByRole(\"checkbox\", { name: \"Need Beans\", exact: true })\n+      .isChecked(),\n+    true,\n+  );\n+  await page.getByRole(\"button\", { name: \"Pantry\", exact: true }).click();\n+  assert.equal(\n+    await page\n+      .getByRole(\"checkbox\", { name: \"Need Lentils\", exact: true })\n+      .count(),\n+    1,\n+  );\n+  observations.push(\n+    \"Observed save failure, failed retry, continued edits, visible unsaved state and successful retry retaining the latest session on reload.\",\n+  );\n+  assert.deepEqual(errors, []);\n+  assert.deepEqual(remote, []);\n+  console.log(\n+    JSON.stringify({\n+      status: \"passed\",\n+      browser: browser.version(),\n+      observations,\n+      pageErrors: errors,\n+      remoteRequests: remote,\n+    }),\n+  );\n+} finally {\n+  if (browser) await browser.close();\n+  await server.close();\n+}\n--- /dev/null\n+++ b/scripts/preview.mjs\n@@ -0,0 +1,61 @@\n+import {