     4	
     5	export function localPersistence(
     6	  getStorage: () => Pick<Storage, "getItem" | "setItem">,
     7	): Persistence {
     8	  return {
     9	    load() {
    10	      const raw = getStorage().getItem(storageKey);
    11	      if (raw === null) return [];
    12	      const parsed: unknown = JSON.parse(raw);
    13	      if (!Array.isArray(parsed)) throw new Error("Invalid pantry data.");
