    15	      return parsed.map((entry: unknown) => {
    16	        if (
    17	          typeof entry !== "object" ||
    18	          entry === null ||
    19	          !("name" in entry) ||
    20	          !("needed" in entry) ||
    21	          typeof entry.name !== "string" ||
    22	          !entry.name.trim() ||
    23	          entry.name !== entry.name.trim() ||
    24	          typeof entry.needed !== "boolean"
    25	        )
    26	          throw new Error("Invalid pantry item.");
    27	        const key = entry.name.toLowerCase();
    28	        if (names.has(key)) throw new Error("Duplicate pantry item.");
    29	        names.add(key);
    30	        return { name: entry.name, needed: entry.needed };
    31	      });
    32	    },
    33	    save(items: readonly Item[]) {
    34	      getStorage().setItem(storageKey, JSON.stringify(items));
    35	    },
    36	  };
    37	}
