p.joinpath('assessment-draft.json').write_text(json.dumps(o,indent=2,ensure_ascii=False)+'\\n')
print(json.dumps({'assessment':str(p/'assessment-draft.json'),'documents':len(o['documents']),'mappedPaths':len(paths),'unmappedPaths':o['unmappedPaths'],'execution':o['execution']}))
